mapper.select:
SELECT * FROM time_entry
WHERE user_id = #{userId} AND date BETWEEN #{start} AND #{end}
ORDER BY date

mapper.update:
UPDATE time_entry
SET clock_in = #{clockIn}, clock_out = #{clockOut}, work_minutes = #{workMinutes}, note = #{note}, version = version + 1, updated_at = #{updatedAt}
WHERE id = #{id} AND version = #{version}
